package org.rabochaya.projects;
import java.io.*;import java.nio.charset.StandardCharsets;
/** Bounded read-only single-frame indexed GIF. Shared raster importer does all projection/rendering. */
public final class GifRaster implements Closeable {
 public static final long MAX_FILE=16L*1024*1024,MAX_PIXELS=4000000;public static final long MAX_DECODE_MILLIS=15000;public final int width,height,palette;public final boolean interlaced,transparent;public final String version;private byte[] pixels;private int[] colors;private boolean closed;
 private GifRaster(int w,int h,int[] colors,byte[] pixels,boolean interlaced,boolean transparent,String version){width=w;height=h;palette=colors.length;this.colors=colors;this.pixels=pixels;this.interlaced=interlaced;this.transparent=transparent;this.version=version;}
 private static IOException bad(String text){return new IOException("GIF: "+text);}
 private static void check(long deadline)throws IOException{if(Thread.currentThread().isInterrupted())throw bad("чтение прервано");if(System.nanoTime()-deadline>=0)throw bad("превышен лимит времени декодирования");}
 private static int u16(RandomAccessFile in)throws IOException{return in.readUnsignedByte()|in.readUnsignedByte()<<8;}
 private static void skip(RandomAccessFile in,long length,int bytes)throws IOException{long at=in.getFilePointer();if(bytes<0||at>length-bytes)throw bad("обрезанные данные");in.seek(at+bytes);}
 private static int blocks(RandomAccessFile in,long length,int[] budget,long deadline)throws IOException{int total=0;for(;;){check(deadline);int n=in.readUnsignedByte();if(n==0)return total;if(++budget[0]>65536)throw bad("больше 65 536 subblocks");skip(in,length,n);total+=n;}}
 private static int[] palette(RandomAccessFile in,int count)throws IOException{int[] colors=new int[count];for(int i=0;i<count;i++)colors[i]=0xff000000|in.readUnsignedByte()<<16|in.readUnsignedByte()<<8|in.readUnsignedByte();return colors;}
 private static final class Bits {
  final RandomAccessFile in;final long length,deadline;final int[] budget;final byte[] block=new byte[255];int at,size,buffer,bits;
  Bits(RandomAccessFile in,long length,int[] budget,long deadline){this.in=in;this.length=length;this.budget=budget;this.deadline=deadline;}
  int code(int width)throws IOException{while(bits<width){if(at==size){check(deadline);int n=in.readUnsignedByte();if(n==0)throw bad("нет LZW end-of-information");if(++budget[0]>65536)throw bad("больше 65 536 subblocks");if(in.getFilePointer()>length-n)throw bad("обрезанные LZW данные");in.readFully(block,0,n);at=0;size=n;}buffer|=(block[at++]&255)<<bits;bits+=8;}int value=buffer&((1<<width)-1);buffer>>>=width;bits-=width;return value;}
  void finish()throws IOException{at=size;blocks(in,length,budget,deadline);}
 }
 private static byte[] decode(RandomAccessFile in,long length,int[] budget,int codeSize,int width,int height,int palette,boolean interlace,long deadline)throws IOException{
  if(codeSize<2||codeSize>8)throw bad("неверный LZW code size");int count=width*height,clear=1<<codeSize,end=clear+1,next=clear+2,bits=codeSize+1,previous=-1,first=0,done=0;byte[] pixels=new byte[count],suffix=new byte[4096],stack=new byte[4096];short[] prefix=new short[4096];for(int i=0;i<clear;i++)suffix[i]=(byte)i;int[] rows=new int[height];int at=0;if(interlace){int[] starts={0,4,2,1},steps={8,8,4,2};for(int pass=0;pass<4;pass++)for(int y=starts[pass];y<height;y+=steps[pass])rows[at++]=y;}else for(int y=0;y<height;y++)rows[y]=y;Bits input=new Bits(in,length,budget,deadline);if(input.code(bits)!=clear)throw bad("первый LZW code должен быть CLEAR");
  for(long codes=0;codes<=2L*count+1024;codes++){if((codes&1023)==0)check(deadline);int code=input.code(bits);if(code==clear){next=clear+2;bits=codeSize+1;previous=-1;continue;}if(code==end){if(done!=count)throw bad("LZW pixel count не совпадает");input.finish();return pixels;}int current=code,top=0;if(current==next){if(previous<0||next>=4096)throw bad("неверный первый/новый LZW code");stack[top++]=(byte)first;current=previous;}else if(current>=next)throw bad("LZW code вне словаря");while(current>=clear){if(current<clear+2||current>=next||top>=stack.length-1)throw bad("повреждённый LZW словарь");stack[top++]=suffix[current];current=prefix[current]&0xffff;}first=current;if(first>=palette)throw bad("LZW index вне палитры");stack[top++]=(byte)first;while(top>0){if((done&4095)==0)check(deadline);int value=stack[--top]&255;if(value>=palette||done>=count)throw bad("LZW index/pixel count вне границ");pixels[rows[done/width]*width+done%width]=(byte)value;done++;}if(previous>=0&&next<4096){prefix[next]=(short)previous;suffix[next]=(byte)first;next++;if(next==(1<<bits)&&bits<12)bits++;}previous=code;}
  throw bad("слишком много LZW codes");
 }
 public static GifRaster read(File source)throws IOException{return read(source,MAX_DECODE_MILLIS);}
 static GifRaster read(File source,long budgetMillis)throws IOException{if(budgetMillis<0||budgetMillis>MAX_DECODE_MILLIS)throw bad("неверный лимит времени");long deadline=System.nanoTime()+budgetMillis*1000000L;check(deadline);try(RandomAccessFile in=new RandomAccessFile(source,"r")){long length=in.length();if(length<14||length>MAX_FILE)throw bad("предел файла 16 МиБ");byte[] stamp=new byte[6];in.readFully(stamp);String version=new String(stamp,StandardCharsets.US_ASCII);if(!version.equals("GIF87a")&&!version.equals("GIF89a"))throw bad("нужен GIF87a/89a");int w=u16(in),h=u16(in),packed=in.readUnsignedByte(),background=in.readUnsignedByte(),aspect=in.readUnsignedByte();if(w<1||h<1||w>20000||h>20000||(long)w*h>MAX_PIXELS||aspect!=0)throw bad("нужны квадратные пиксели, до 20k по стороне / 4 млн пикселей");int global=(packed&128)!=0?1<<((packed&7)+1):0;int[] globalColors=null,colors=null;byte[] pixels=null;if(global>0){if(background>=global)throw bad("неверный background index");globalColors=palette(in,global);}boolean gce=false,alpha=false,frame=false,interlace=false;int transparentIndex=0;int[] budget={0};
  for(int records=0;records<1024;records++){check(deadline);int tag=in.readUnsignedByte();if(tag==0x3b){if(!frame||in.getFilePointer()!=length)throw bad("нет полного кадра/лишние данные");return new GifRaster(w,h,colors,pixels,interlace,alpha,version);}
   if(tag==0x21){if(!version.equals("GIF89a"))throw bad("расширения требуют GIF89a");int kind=in.readUnsignedByte();if(kind==0xfe){blocks(in,length,budget,deadline);continue;}if(kind!=0xf9||frame||gce||in.readUnsignedByte()!=4)throw bad("поддержан один статический кадр, без application/plaintext/повторных GCE");int flags=in.readUnsignedByte(),delay=u16(in);transparentIndex=in.readUnsignedByte();if(in.readUnsignedByte()!=0||(flags&0xe2)!=0||((flags>>2)&7)>1||delay!=0)throw bad("анимация/user input/disposal/reserved flags не поддержаны");alpha=(flags&1)!=0;gce=true;continue;}
   if(tag!=0x2c||frame)throw bad("поддержан ровно один image descriptor");int left=u16(in),top=u16(in),fw=u16(in),fh=u16(in),flags=in.readUnsignedByte();if(left!=0||top!=0||fw!=w||fh!=h||(flags&0x18)!=0)throw bad("нужен полный кадр без crop/reserved flags");interlace=(flags&64)!=0;colors=(flags&128)!=0?palette(in,1<<((flags&7)+1)):globalColors;if(colors==null)throw bad("нет палитры");if(alpha){if(transparentIndex>=colors.length)throw bad("неверный transparent index");colors[transparentIndex]=0;}pixels=decode(in,length,budget,in.readUnsignedByte(),w,h,colors.length,interlace,deadline);frame=true;
  }throw bad("больше 1024 records");
 }catch(EOFException e){throw bad("обрезанная структура");}}
 public synchronized int pixel(int x,int y)throws IOException{if(closed)throw bad("reader закрыт");if(x<0||y<0||x>=width||y>=height)return 0;return colors[pixels[y*width+x]&255];}
 public synchronized void close(){closed=true;pixels=null;colors=null;}
}
